INSERT INTO math_practice_quizzes (title, description, questions, class_id, created_at) 
VALUES ( 'Mathematics Arithmetic Quiz', 'A quiz designed to test basic arithmetic skills including addition, subtraction, multiplication, and division.', '[{"id": "q1", "type": "fillInBlank", "question": "707 \u2212 10 = ___", "hint": "Think about how much you decrease from 707.", "explanation": "Subtracting 10 from 707 gives you 697.", "correctAnswer": "697"}, {"id": "q2", "type": "fillInBlank", "question": "6,138 + 456 = ___", "hint": "Add the two numbers together.", "explanation": "Adding 6,138 and 456 results in 6,594.", "correctAnswer": "6594"}, {"id": "q3", "type": "mcq", "question": "What is 10 \u00d7 96?", "hint": "Multiply 10 by 96.", "explanation": "10 times 96 equals 960.", "correctAnswer": "a", "options": [{"id": "a", "text": "960"}, {"id": "b", "text": "970"}, {"id": "c", "text": "950"}, {"id": "d", "text": "940"}]}, {"id": "q4", "type": "fillInBlank", "question": "2,800 \u00f7 7 = ___", "hint": "How many times does 7 go into 2800?", "explanation": "Dividing 2,800 by 7 gives you 400.", "correctAnswer": "400"}, {"id": "q5", "type": "multiSelect", "question": "Which of the following are equivalent to 50% of 700?", "hint": "Think about what half of 700 is.", "explanation": "50% of 700 is 350.", "correctAnswer": ["a"], "options": [{"id": "a", "text": "350"}, {"id": "b", "text": "300"}, {"id": "c", "text": "400"}, {"id": "d", "text": "500"}]}]', 'ef76faf5-707e-4387-9b7b-4b4894b6b548', NOW());

INSERT INTO math_practice_quizzes (title, description, questions, class_id, created_at) 
VALUES ( 'Mathematics Reasoning Quiz', 'A quiz designed to test reasoning skills in mathematics for Key Stage 2 students, covering various topics including time, temperature, geometry, and basic arithmetic.', '[{"id": "q1", "type": "mcq", "question": "What time does the clock show if it is 5 minutes past 11?", "hint": "Think about how the minute hand moves on the clock.", "explanation": "5 minutes past 11 means the minute hand is on the 1, which indicates 11:05.", "correctAnswer": "a", "options": [{"id": "a", "text": "11:05"}, {"id": "b", "text": "10:55"}, {"id": "c", "text": "11:10"}, {"id": "d", "text": "12:05"}]}, {"id": "q2", "type": "multiSelect", "question": "Which of the following temperatures are below freezing?", "hint": "Freezing point is 0\u00b0C.", "explanation": "Temperatures below 0\u00b0C are considered below freezing, which includes -4\u00b0C and -10\u00b0C.", "correctAnswer": ["b", "d"], "options": [{"id": "a", "text": "6\u00b0C"}, {"id": "b", "text": "-4\u00b0C"}, {"id": "c", "text": "1\u00b0C"}, {"id": "d", "text": "-10\u00b0C"}, {"id": "e", "text": "3\u00b0C"}]}, {"id": "q3", "type": "fillInBlank", "question": "The coordinates of point C in triangle ABC are (___, ___).", "hint": "Look at the grid to find the position of point C.", "explanation": "Point C is located at the intersection of x=2 and y=3 on the grid.", "correctAnswer": "(2, 3)"}, {"id": "q4", "type": "mcq", "question": "How many more children chose tiger than elephant?", "hint": "Count the number of children for each animal.", "explanation": "If 6 children chose tiger and 2 chose elephant, then 6 - 2 = 4 more children chose tiger.", "correctAnswer": "b", "options": [{"id": "a", "text": "2"}, {"id": "b", "text": "4"}, {"id": "c", "text": "6"}, {"id": "d", "text": "8"}]}, {"id": "q5", "type": "fillInBlank", "question": "Kirsty buys 1 litre of apple juice for \u00a31.39 and pays with a \u00a35 note. She gets \u00a3___ in change.", "hint": "Subtract the cost from the amount paid.", "explanation": "To find the change, subtract \u00a31.39 from \u00a35.00, which equals \u00a33.61.", "correctAnswer": "3.61"}]', 'ef76faf5-707e-4387-9b7b-4b4894b6b548', NOW());

INSERT INTO math_practice_quizzes (title, description, questions, class_id, created_at) 
VALUES ( 'Mathematics Reasoning Quiz', 'A quiz designed to test reasoning skills in mathematics for Key Stage 2 students, covering various topics including number sequences, shapes, and basic arithmetic.', '[{"id": "q1", "type": "fillInBlank", "question": "Chen has the digit cards 4, 8, 2, and 7. If she puts the 4 in the tens place, the lowest three-digit number she could make is ___.", "hint": "Think about the smallest digits available for the hundreds and units places.", "explanation": "The lowest three-digit number with 4 in the tens place is 204, using 2 for the hundreds and 0 for the units.", "correctAnswer": "204"}, {"id": "q2", "type": "mcq", "question": "Which of the following numbers is eighty thousand, three hundred and six?", "hint": "Look for the number that matches the place values of each digit.", "explanation": "80,306 is the correct representation of eighty thousand, three hundred and six.", "correctAnswer": "c", "options": [{"id": "a", "text": "8,306"}, {"id": "b", "text": "80,036"}, {"id": "c", "text": "80,306"}, {"id": "d", "text": "800,306"}]}, {"id": "q3", "type": "multiSelect", "question": "Circle the two decimals that round to the same whole number.", "hint": "Consider how each decimal rounds to the nearest whole number.", "explanation": "14.7 rounds to 15 and 15.9 also rounds to 16, making them the two decimals that round to the same whole number.", "correctAnswer": ["b", "c"], "options": [{"id": "a", "text": "13.2"}, {"id": "b", "text": "14.7"}, {"id": "c", "text": "15.9"}, {"id": "d", "text": "16.3"}, {"id": "e", "text": "17.6"}]}, {"id": "q4", "type": "fillInBlank", "question": "Write the missing number to make the calculation correct: 1,300,450 = 1,000,000 + ___ + 400 + 50.", "hint": "Subtract the known values from 1,300,450.", "explanation": "To find the missing number, calculate 1,300,450 - 1,000,000 - 400 - 50, which equals 300.", "correctAnswer": "300"}, {"id": "q5", "type": "mcq", "question": "What fraction of the area of the rectangle is shaded if Part A is 1/2 and Part B is 1/3?", "hint": "Add the fractions of the shaded parts together.", "explanation": "The total shaded area is 1/2 + 1/3 = 3/6 + 2/6 = 5/6.", "correctAnswer": "b", "options": [{"id": "a", "text": "1/6"}, {"id": "b", "text": "5/6"}, {"id": "c", "text": "1/2"}, {"id": "d", "text": "1/3"}]}]', 'ef76faf5-707e-4387-9b7b-4b4894b6b548', NOW());

INSERT INTO math_practice_quizzes (title, description, questions, class_id, created_at) 
VALUES ( 'Mathematics Arithmetic Quiz', 'A quiz designed to test basic arithmetic skills including addition, subtraction, multiplication, and division.', '[{"id": "q1", "type": "fillInBlank", "question": "6,155 + 501 + 649 = ___", "hint": "Add the three numbers together.", "explanation": "The sum of 6,155, 501, and 649 is 7,305.", "correctAnswer": "7305"}, {"id": "q2", "type": "fillInBlank", "question": "0 \u00d7 989 = ___", "hint": "Any number multiplied by zero equals zero.", "explanation": "Multiplying any number by zero results in zero.", "correctAnswer": "0"}, {"id": "q3", "type": "fillInBlank", "question": "10 + ___ = 302", "hint": "Subtract 10 from 302.", "explanation": "To find the missing number, subtract 10 from 302, which gives 292.", "correctAnswer": "292"}, {"id": "q4", "type": "fillInBlank", "question": "2,400 \u00f7 2 = ___", "hint": "Divide 2,400 by 2.", "explanation": "Dividing 2,400 by 2 results in 1,200.", "correctAnswer": "1200"}, {"id": "q5", "type": "fillInBlank", "question": "7,306 \u2212 1,847 = ___", "hint": "Subtract 1,847 from 7,306.", "explanation": "The difference between 7,306 and 1,847 is 5,459.", "correctAnswer": "5459"}]', 'ef76faf5-707e-4387-9b7b-4b4894b6b548', NOW());

INSERT INTO math_practice_quizzes (title, description, questions, class_id, created_at) 
VALUES ( 'Mathematics Reasoning Quiz', 'A quiz designed to test reasoning skills in mathematics, covering various topics such as addition, estimation, fractions, and basic operations.', '[{"id": "q1", "type": "mcq", "question": "Circle the greatest number: 9,206,499, 9,215,300, 9,206,504, 9,215,298.", "hint": "Look for the number with the highest value in the millions place.", "explanation": "9,215,300 is the greatest number because it has the highest value in the millions place compared to the others.", "correctAnswer": "b", "options": [{"id": "a", "text": "9,206,499"}, {"id": "b", "text": "9,215,300"}, {"id": "c", "text": "9,206,504"}, {"id": "d", "text": "9,215,298"}]}, {"id": "q2", "type": "fillInBlank", "question": "One table can seat 8 people. How many tables are needed to seat 40 people? ___ tables.", "hint": "Divide the total number of people by the number of people per table.", "explanation": "To find the number of tables needed, divide 40 by 8, which equals 5.", "correctAnswer": "5"}, {"id": "q3", "type": "mcq", "question": "Children estimated the number of beans in a jar. The exact number is 1,380. Whose estimate was closest? Amir (1,310), Olivia (1,220), Emma (1,400), John (1,290), Chen (1,460).", "hint": "Compare each estimate to the exact number.", "explanation": "Emma''s estimate of 1,400 is closest to the exact number of 1,380.", "correctAnswer": "c", "options": [{"id": "a", "text": "Amir"}, {"id": "b", "text": "Olivia"}, {"id": "c", "text": "Emma"}, {"id": "d", "text": "John"}, {"id": "e", "text": "Chen"}]}, {"id": "q4", "type": "fillInBlank", "question": "A truck can carry a load of 2.3 tonnes. How many kilograms can the truck carry? ___ kg.", "hint": "Remember that 1 tonne equals 1,000 kilograms.", "explanation": "To convert tonnes to kilograms, multiply 2.3 by 1,000, which equals 2,300 kg.", "correctAnswer": "2300"}, {"id": "q5", "type": "multiSelect", "question": "Tick the numbers that round to 28.7: 28.07, 28.65, 28.71, 28.75, 28.97.", "hint": "Consider which numbers are closest to 28.7 when rounded.", "explanation": "28.71 and 28.75 round to 28.7 when considering one decimal place.", "correctAnswer": ["c", "d"], "options": [{"id": "a", "text": "28.07"}, {"id": "b", "text": "28.65"}, {"id": "c", "text": "28.71"}, {"id": "d", "text": "28.75"}, {"id": "e", "text": "28.97"}]}]', 'ef76faf5-707e-4387-9b7b-4b4894b6b548', NOW());

INSERT INTO math_practice_quizzes (title, description, questions, class_id, created_at) 
VALUES ( 'Mathematics Reasoning Quiz', 'A quiz designed to test reasoning skills in mathematics, covering various topics including basic arithmetic, geometry, and number theory.', '[{"id": "q1", "type": "mcq", "question": "How many faces does a hexagonal prism have?", "hint": "Consider the number of faces on the top and bottom, plus the lateral faces.", "explanation": "A hexagonal prism has 2 hexagonal faces and 6 rectangular lateral faces, totaling 8 faces.", "correctAnswer": "c", "options": [{"id": "a", "text": "6"}, {"id": "b", "text": "8"}, {"id": "c", "text": "10"}, {"id": "d", "text": "12"}]}, {"id": "q2", "type": "fillInBlank", "question": "Olivia buys a banana, an apple, and a bag of nuts for 30p, 45p, and 60p respectively. She pays with three 50p coins. Her change is ___ p.", "hint": "Calculate the total cost and subtract it from the amount paid.", "explanation": "The total cost is 30 + 45 + 60 = 135p. Olivia pays 150p, so her change is 150 - 135 = 15p.", "correctAnswer": "15"}, {"id": "q3", "type": "multiSelect", "question": "Match the following fractions to their equivalent decimals.", "hint": "Convert each fraction to a decimal by dividing the numerator by the denominator.", "explanation": "1/2 = 0.5, 3/4 = 0.75, and 1/4 = 0.25.", "correctAnswer": ["a", "d", "b", "e", "c", "f"], "options": [{"id": "a", "text": "1/2"}, {"id": "b", "text": "3/4"}, {"id": "c", "text": "1/4"}, {"id": "d", "text": "0.5"}, {"id": "e", "text": "0.75"}, {"id": "f", "text": "0.25"}]}, {"id": "q4", "type": "mcq", "question": "What is the total cost of hiring a hall from 6 pm until 11 pm if the booking fee is \u00a315 and the hourly rate is \u00a312.50?", "hint": "Calculate the number of hours and multiply by the hourly rate, then add the booking fee.", "explanation": "The total cost is \u00a315 + (5 hours * \u00a312.50) = \u00a315 + \u00a362.50 = \u00a377.50.", "correctAnswer": "b", "options": [{"id": "a", "text": "\u00a375"}, {"id": "b", "text": "\u00a362.50"}, {"id": "c", "text": "\u00a350"}, {"id": "d", "text": "\u00a380"}]}, {"id": "q5", "type": "fillInBlank", "question": "Jack hires a hall for a party. The total cost is \u00a315 booking fee plus \u00a312.50 per hour. If he hires it for 5 hours, the total cost is ___ \u00a3.", "hint": "Multiply the hourly rate by the number of hours and add the booking fee.", "explanation": "Total cost = \u00a315 + (5 * \u00a312.50) = \u00a315 + \u00a362.50 = \u00a377.50.", "correctAnswer": "\u00a377.50"}]', 'ef76faf5-707e-4387-9b7b-4b4894b6b548', NOW());

